-- LXC360 R2 / Add 10 distinctive native popup compositions (run after lifecycle R1)
-- System definitions are additive and never overwrite previously customized campaigns.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('angelcare:live360:popup-themes'));
ON CONFLICT (theme_key) DO NOTHING;
DO $plpgsql$ DECLARE count_themes integer; BEGIN SELECT count(*) INTO count_themes FROM public.angelcare_marketplace_live_experience_themes WHERE theme_key LIKE 'popup_%' AND theme_key=ANY(ARRAY['popup_atrium_editorial','popup_terracotta_terrace','popup_botanical_care','popup_lilac_editorial','popup_compact_precision','popup_bento_mosaic','popup_museum_gallery','popup_glass_aurora','popup_heritage_ledger','popup_warm_cinema']);IF count_themes<>10 THEN RAISE EXCEPTION 'Expected 10 new popup themes, got %',count_themes;END IF;END $plpgsql$;
COMMIT;
